import{_ as a,o,c as d,af as c}from"./chunks/framework.zl0XNxp1.js";const p=JSON.parse('{"title":"迪庆藏族自治州——香格里拉 - 2025","description":"","frontmatter":{},"headers":[],"relativePath":"2_articles/travel_record/XiangGeLiLa.md","filePath":"2_articles/travel_record/XiangGeLiLa.md","lastUpdatedText":"2025-07-23 22:50:27"}'),t={name:"2_articles/travel_record/XiangGeLiLa.md"};function r(i,e,l,n,h,_){return o(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="迪庆藏族自治州——香格里拉-2025" tabindex="-1">迪庆藏族自治州——香格里拉 - 2025 <a class="header-anchor" href="#迪庆藏族自治州——香格里拉-2025" aria-label="Permalink to &quot;迪庆藏族自治州——香格里拉 - 2025&quot;">​</a></h1><h2 id="_6月13日-6月16日-☀️" tabindex="-1">6月13日 - 6月16日 ☀️ <a class="header-anchor" href="#_6月13日-6月16日-☀️" aria-label="Permalink to &quot;6月13日 - 6月16日 ☀️&quot;">​</a></h2><blockquote><p>我和黛黛同学本科毕业旅行的第四站，距离天堂最近的地方！</p></blockquote><h3 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h3><p>云南三部曲之<code>香格里拉</code>, 小时候看<code>查理九世</code>知道的这座城市，记得那部书的名字叫<code>香巴拉——世界的尽头</code>，我的心中也一直对这座城市充满好奇，这次终于有机会我们一起去探索下这座位于4400米海拔的神秘城市。</p><h3 id="_6月13日" tabindex="-1">6月13日 <a class="header-anchor" href="#_6月13日" aria-label="Permalink to &quot;6月13日&quot;">​</a></h3><p>下午抵达香格里拉，刚到站就下雨了，在高铁站躲了一会雨顺便等车来，之后坐车一路沿着景点到民宿，刚到这座城市的感慨就是这里的人真的<code>热情和善良</code>，司机一路上为我们介绍景点和怎么去最省力省钱，还有妆造推荐，到达民宿老板都开好房间后才发现我俩好像没订成功，站在前台找了半天没找到订单，结果老板直接给我们最低价住最好的房间，比网上订便宜一半，三晚全按最低价算，而且这家民宿是真的美，老板是徒步爱好者，之前徒步到这边，觉得这边很美就在这边开了民宿定居，养了一只土柴叫<code>七七</code>,每天和游客一起喝酒聊天。放好东西后，我们在<code>独克宗古城</code>吃了非常出名的<code>牦牛</code>火锅，老板还给我们献了<code>哈达</code>，但刚到这里还没入乡随俗，傻傻的说了句谢谢，应该也回应<code>扎西德勒</code>的，老板还给送了藏族特色冰淇淋。吃完后在古城里的<code>月光广场</code>上和大家合唱、跳藏族舞，一起大叫嗨皮，氛围真的无敌。之后我们又去了<code>龟山公园</code>，转了<code>转经筒</code>，下来后在超市买了干粮和零食，准备第二天前往<code>普达措国家公园</code>。结果半夜的我高反发烧了，给黛黛忙活了半夜😭</p><h3 id="_6月14日" tabindex="-1">6月14日 <a class="header-anchor" href="#_6月14日" aria-label="Permalink to &quot;6月14日&quot;">​</a></h3><p>一大早起来还是高烧不退，点外卖买了退烧药，喝了药后感觉能顶得住，就出去吃了早餐到景区等车点，等车的时候晒了半天太阳感觉直接退烧了，坐上车出发<code>普达措</code>，到达后怕徒步高反，高价买了氧气瓶，结果完全没用到.....从<code>幽悠步道</code>一直徒步到终点，一路上看到一群黑pig和牦牛，感受大自然的原生态，别人都是一路看看风景，我俩一路目的不纯，偷偷在路上摘菌子哈哈哈，捡了好几种菌子，在普达措里垒了<code>玛尼堆</code>祈福，看到了小学语文课本上想象的<code>草原溪流</code>，也拍了很多美照，吃了一路的辣条🤠，下午回古城，在提前订好的妆造店看了妆造，去吃了本地特色菜，直接给牦牛肉吃腻了，晚上又在月光广场上跟大家一起嗨皮，后面太冷就回去洗衣服休息了。</p><h3 id="_6月15日" tabindex="-1">6月15日 <a class="header-anchor" href="#_6月15日" aria-label="Permalink to &quot;6月15日&quot;">​</a></h3><p>早上起来又发烧，点了早餐，喝了药退烧后又重感冒，一直流鼻涕，去妆造店选了衣服，穿上了<code>藏族特色服饰</code>，然后我们就出发具有小布达拉宫之称的<code>松赞林寺</code>，两个人傻傻的看攻略没买景区车票，一路徒步三四公里才到，路上遇到徒步的小姐姐给我们加油哈哈，在松赞林寺拍了非常多的大片，简直美爆😀，中午回去吃了碗<code>兰州拉面</code>，看着快下雨了就直接出发<code>大经幡</code>，又在这里美美拍了一下午，下午回去后又在本地苍蝇小馆里吃了非常美味的特色菜，卸了妆造后又在古城嗨皮了半天，买了第二天的零食水果就休息啦。</p><h3 id="_6月16日" tabindex="-1">6月16日 <a class="header-anchor" href="#_6月16日" aria-label="Permalink to &quot;6月16日&quot;">​</a></h3><p>起来后已经完全不发烧了，收拾行李吃了早饭后就去了高铁站，坐车出发毕业旅行第五站<code>成都</code>！</p>',13)])])}const u=a(t,[["render",r]]);export{p as __pageData,u as default};
